import{_ as l,o as i,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-10-08","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-10-08","date":"2025-10-08T00:00:00.000Z","updated":"2025-10-16T00:00:00.000Z","tags":["Ceph","RGW","S3测试","测试框架","版本化存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-10-08.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-10-08.md","lastUpdated":1780460162000}'),t={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-10-08.md"};function r(n,e,d,h,c,s){return i(),a("div",null,[...e[0]||(e[0]=[o('<h3 id="ceph-rgw-重构会议纪要-2025-10-08" tabindex="-1">Ceph RGW 重构会议纪要（2025-10-08） <a class="header-anchor" href="#ceph-rgw-重构会议纪要-2025-10-08" aria-label="Permalink to &quot;Ceph RGW 重构会议纪要（2025-10-08）&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><p>本次会议主要讨论了以下议题：</p><ol><li>S3 测试中的 Boto2 迁移问题</li><li>S3 测试仓库迁移至 Ceph 主仓库</li><li>Ragweed 测试框架的未来</li><li>RGW 版本化存储桶索引限制与改进方案</li></ol><h4 id="_1-s3-测试中的-boto2-迁移问题" tabindex="-1">1. S3 测试中的 Boto2 迁移问题 <a class="header-anchor" href="#_1-s3-测试中的-boto2-迁移问题" aria-label="Permalink to &quot;1. S3 测试中的 Boto2 迁移问题&quot;">​</a></h4><p><strong>讨论内容</strong>：</p><ul><li>问题：由于新版 Python 不再支持 <code>boto2</code>，导致 S3 测试失败。</li><li>解决方案： <ul><li>移除 <code>boto2</code> 依赖，并提交相关 PR。</li><li>使用 Fuzzing 替代手工构造的无效请求测试。</li></ul></li><li>后续行动： <ul><li>重新提交并合并移除 <code>boto2</code> 的 PR。</li><li>评估 Fuzzing 在 S3 API 测试中的适用性。</li></ul></li></ul><h4 id="_2-s3-测试仓库迁移至-ceph-主仓库" tabindex="-1">2. S3 测试仓库迁移至 Ceph 主仓库 <a class="header-anchor" href="#_2-s3-测试仓库迁移至-ceph-主仓库" aria-label="Permalink to &quot;2. S3 测试仓库迁移至 Ceph 主仓库&quot;">​</a></h4><p><strong>讨论内容</strong>：</p><ul><li>背景：S3 测试独立仓库导致 QA 流程复杂。</li><li>进展：Adam 已提供 POC，验证迁移可行性。</li><li>优势：简化测试流程，统一管理。</li><li>后续行动：推进迁移工作，解决技术细节后合并至主仓库。</li></ul><h4 id="_3-ragweed-测试框架的未来" tabindex="-1">3. Ragweed 测试框架的未来 <a class="header-anchor" href="#_3-ragweed-测试框架的未来" aria-label="Permalink to &quot;3. Ragweed 测试框架的未来&quot;">​</a></h4><p><strong>讨论内容</strong>：</p><ul><li>现状：Ragweed 用于跨版本升级测试，但近年未新增重要测试用例，存在 <code>boto2</code> 依赖问题。</li><li>争议： <ul><li>保留：支持非 S3 API 测试，适合跨版本兼容性验证。</li><li>废弃：维护成本高，测试覆盖有限。</li></ul></li><li>后续行动： <ul><li>暂不废弃，但需明确其定位。</li><li>鼓励社区贡献简化方案或替代工具。</li></ul></li></ul><h4 id="_4-rgw-版本化存储桶索引限制与改进方案" tabindex="-1">4. RGW 版本化存储桶索引限制与改进方案 <a class="header-anchor" href="#_4-rgw-版本化存储桶索引限制与改进方案" aria-label="Permalink to &quot;4. RGW 版本化存储桶索引限制与改进方案&quot;">​</a></h4><p><strong>讨论内容</strong>：</p><ul><li>问题：版本化存储桶的索引分片要求同一对象的所有版本必须位于同一分片，导致单对象版本过多时分片可能超过 OMAP 的限制。</li><li>改进方向： <ul><li>有序索引：支持版本跨分片存储，通过分片动态拆分/合并优化负载。</li><li>事务模型调整：解决跨分片事务一致性。</li><li>版本数量限制：默认限制可防止意外问题，但需支持用户自定义或“无限制”场景。</li></ul></li><li>后续行动： <ul><li>Eric 深入研究 <code>OH epoch</code> 与分片路由的关系，优化事务模型。</li><li>社区讨论版本限制的默认值与错误处理。</li></ul></li></ul><h4 id="行动计划总结" tabindex="-1">行动计划总结 <a class="header-anchor" href="#行动计划总结" aria-label="Permalink to &quot;行动计划总结&quot;">​</a></h4><ul><li>合并移除 <code>boto2</code> 的 PR。</li><li>S3 测试仓库迁移至主仓库。</li><li>Ragweed 框架评估。</li><li>RGW 有序索引开发。</li></ul>',18)])])}const p=l(t,[["render",r]]);export{_ as __pageData,p as default};
